const GRAPH_API_VERSION = "v21.0";
const BASE_URL = `https://graph.facebook.com/${GRAPH_API_VERSION}`;
const INSTAGRAM_AUTH_URL = "https://api.instagram.com/oauth/access_token";
const INSTAGRAM_GRAPH_BASE_URL = `https://graph.instagram.com/${GRAPH_API_VERSION}`;
const DEFAULT_TIMEOUT_MS = 15000;

function getGraphBaseUrl(token) {
  if (token && typeof token === "string" && token.startsWith("IGAA")) {
    return INSTAGRAM_GRAPH_BASE_URL;
  }
  return BASE_URL;
}


function getAppAccessToken() {
  const appId = process.env.INSTAGRAM_APP_ID?.trim();
  const appSecret = process.env.INSTAGRAM_APP_SECRET?.trim();
  if (!appId || !appSecret) return null;
  return `${appId}|${appSecret}`;
}

async function fetchJson(url, init = {}, { timeoutMs = DEFAULT_TIMEOUT_MS } = {}) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(url, { ...init, signal: controller.signal });
    const data = await response.json().catch(() => null);
    return { response, data };
  } finally {
    clearTimeout(timeout);
  }
}

/**
 * Meta API Helper Functions
 */
export const MetaService = {
  // --- OAUTH FLOW HELPERS ---

  /**
   * Exchange Instagram Login for Business code for a short-lived Instagram token.
   */
  exchangeInstagramCodeForToken: async (code, redirectUri) => {
    try {
      const body = new URLSearchParams({
        client_id: process.env.INSTAGRAM_APP_ID?.trim(),
        client_secret: process.env.INSTAGRAM_APP_SECRET?.trim(),
        grant_type: "authorization_code",
        redirect_uri: redirectUri,
        code,
      });

      const { response, data } = await fetchJson(INSTAGRAM_AUTH_URL, {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body,
      });

      if (!response.ok) {
        throw new Error(data?.error_message || data?.error?.message || "Instagram code exchange failed");
      }

      return {
        success: true,
        accessToken: data.access_token,
        userId: data.user_id,
        permissions: data.permissions || [],
      };
    } catch (error) {
      console.error("Instagram OAuth - exchangeCodeForToken Error:", error.message);
      return { success: false, error: error.message };
    }
  },

  /**
   * Convert short-lived Instagram token to a long-lived token.
   */
  getLongLivedInstagramToken: async (shortToken) => {
    try {
      const params = new URLSearchParams({
        grant_type: "ig_exchange_token",
        client_secret: process.env.INSTAGRAM_APP_SECRET?.trim(),
        access_token: shortToken,
      });

      const { response, data } = await fetchJson(
        `https://graph.instagram.com/access_token?${params.toString()}`
      );

      if (!response.ok) {
        throw new Error(data?.error?.message || "Instagram long-lived token exchange failed");
      }

      return {
        success: true,
        accessToken: data.access_token,
        expiresIn: data.expires_in,
      };
    } catch (error) {
      console.error("Instagram OAuth - getLongLivedToken Error:", error.message);
      return { success: false, error: error.message };
    }
  },

  /**
   * Fetch the connected Instagram Business/Creator profile.
   */
  getInstagramProfile: async (accessToken) => {
    try {
      const fields = "id,user_id,username,name,account_type,profile_picture_url";
      const { response, data } = await fetchJson(
        `${INSTAGRAM_GRAPH_BASE_URL}/me?fields=${fields}&access_token=${accessToken}`
      );

      if (!response.ok) {
        throw new Error(data?.error?.message || "Failed to fetch Instagram profile");
      }

      return { success: true, data };
    } catch (error) {
      console.error("Instagram API - getInstagramProfile Error:", error.message);
      return { success: false, error: error.message };
    }
  },

  /**
   * 1. Exchange short-lived User Code for User Token
   */
  exchangeCodeForToken: async (code, redirectUri) => {
    try {
      const params = new URLSearchParams({
        client_id: process.env.INSTAGRAM_APP_ID?.trim(),
        client_secret: process.env.INSTAGRAM_APP_SECRET?.trim(),
        redirect_uri: redirectUri,
        code: code,
      });

      const response = await fetch(`${BASE_URL}/oauth/access_token?${params.toString()}`);
      const data = await response.json();
      if (!response.ok) throw new Error(data.error?.message || "Code exchange failed");
      return { success: true, accessToken: data.access_token };
    } catch (error) {
      console.error("Meta API - exchangeCodeForToken Error:", error.message);
      return { success: false, error: error.message };
    }
  },

  /**
   * 2. Convert short-lived token to long-lived (60 days)
   */
  getLongLivedToken: async (shortToken) => {
    try {
      const params = new URLSearchParams({
        grant_type: 'fb_exchange_token',
        client_id: process.env.INSTAGRAM_APP_ID?.trim(),
        client_secret: process.env.INSTAGRAM_APP_SECRET?.trim(),
        fb_exchange_token: shortToken,
      });

      const response = await fetch(`${BASE_URL}/oauth/access_token?${params.toString()}`);
      const data = await response.json();
      if (!response.ok) throw new Error(data.error?.message || "Long-lived token exchange failed");
      return { success: true, accessToken: data.access_token };
    } catch (error) {
      console.error("Meta API - getLongLivedToken Error:", error.message);
      return { success: false, error: error.message };
    }
  },

  /**
   * 3. Fetch Instagram Business Accounts from User Pages
   */
  getInstagramAccounts: async (userAccessToken) => {
    try {
      // Step A: Get pages managed by user
      const { response, data } = await fetchJson(
        `${BASE_URL}/me/accounts?fields=name,access_token,instagram_business_account&access_token=${userAccessToken}`
      );
      
      if (!response.ok) throw new Error(data.error?.message || "Failed to fetch pages");

      // Step B: Filter pages that HAVE an Instagram Business Account linked
      const igAccounts = data.data
        .filter(page => page.instagram_business_account)
        .map(page => ({
          page_id: page.id,
          page_name: page.name,
          page_token: page.access_token,
          instagram_business_id: page.instagram_business_account.id
        }));

      return { success: true, accounts: igAccounts };
    } catch (error) {
      console.error("Meta API - getInstagramAccounts Error:", error.message);
      return { success: false, error: error.message };
    }
  },

  /**
   * Fetch IG business account id for a given Page using its Page access token.
   * Useful when only the Page access token is stored (no long-lived user token).
   */
  getInstagramBusinessIdFromPage: async (pageId, pageAccessToken) => {
    try {
      if (!pageId) throw new Error("Missing pageId");
      if (!pageAccessToken) throw new Error("Missing pageAccessToken");

      const { response, data } = await fetchJson(
        `${BASE_URL}/${pageId}?fields=instagram_business_account&access_token=${pageAccessToken}`
      );

      if (!response.ok) throw new Error(data?.error?.message || "Failed to fetch page fields");

      const instagramBusinessId = data?.instagram_business_account?.id || null;
      return { success: true, instagramBusinessId };
    } catch (error) {
      console.error("Meta API - getInstagramBusinessIdFromPage Error:", error.message);
      return { success: false, instagramBusinessId: null, error: error.message };
    }
  },

  /**
   * Debug a token (shows granted scopes / granular scopes).
   * This requires INSTAGRAM_APP_ID + INSTAGRAM_APP_SECRET server-side.
   */
  debugToken: async (inputToken) => {
    try {
      const appToken = getAppAccessToken();
      if (!appToken) throw new Error("Missing INSTAGRAM_APP_ID / INSTAGRAM_APP_SECRET");
      if (!inputToken) throw new Error("Missing inputToken");

      const params = new URLSearchParams({
        input_token: inputToken,
        access_token: appToken,
      });

      const { response, data } = await fetchJson(`${BASE_URL}/debug_token?${params.toString()}`);
      if (!response.ok) throw new Error(data?.error?.message || "debug_token failed");

      return { success: true, data: data?.data || data };
    } catch (error) {
      return { success: false, error: error.message };
    }
  },

  // --- CORE MESSAGING & ACTIONS ---

  getUserProfile: async (userId, accessToken) => {
    try {
      const response = await fetch(`${getGraphBaseUrl(accessToken)}/${userId}?fields=name,profile_pic&access_token=${accessToken}`);
      const data = await response.json();
      if (!response.ok) throw new Error(data.error?.message || "Failed to fetch user profile");
      return { success: true, data };
    } catch (error) {
      // Silence Error #230 (Consent required) as it's expected for new commenters
      if (!error.message.includes("(#230)")) {
        console.error("Meta API - getUserProfile Error:", error.message);
      }
      return { success: false, error: error.message };
    }
  },

  sendDM: async (recipientId, text, accessToken) => {
    if (!text || text.trim() === "") {
      console.warn("Meta API - sendDM: attempted to send empty text. Skipping.");
      return { success: false, error: "Empty text" };
    }
    try {
      const response = await fetch(`${getGraphBaseUrl(accessToken)}/me/messages?access_token=${accessToken}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          recipient: { id: recipientId },
          message: { text: text },
        }),
      });
      const data = await response.json();
      if (!response.ok) {
        console.error(`Meta API sendDM Error [${response.status}]:`, data.error?.message || "Unknown error");
        throw new Error(data.error?.message || "Failed to send DM");
      }
      return { success: true, data };
    } catch (error) {
      return { success: false, error: error.message };
    }
  },

  sendPrivateReply: async (commentId, messagePayload, accessToken) => {
    try {
      // Support both simple text and structured message objects (for quick_replies)
      const messageBody = typeof messagePayload === 'string' 
        ? { text: messagePayload } 
        : messagePayload;

      const response = await fetch(`${getGraphBaseUrl(accessToken)}/me/messages?access_token=${accessToken}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ 
          recipient: { comment_id: commentId },
          message: messageBody 
        }),
      });
      const data = await response.json();
      if (!response.ok) {
         console.error("Meta API PrivateReply Error:", data.error?.message);
         throw new Error(data.error?.message || "Failed to send private reply");
      }
      return { success: true, data };
    } catch (error) {
      return { success: false, error: error.message };
    }
  },

  sendCommentReply: async (commentId, text, accessToken) => {
    try {
      const response = await fetch(`${getGraphBaseUrl(accessToken)}/${commentId}/replies?access_token=${accessToken}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: text }),
      });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error?.message || "Failed to reply to comment");
      return { success: true, data };
    } catch (error) {
      console.error("Meta API - sendCommentReply Error:", error.message);
      return { success: false, error: error.message };
    }
  },

  checkFollowStatus: async (userId, accessToken) => {
    try {
      const response = await fetch(`${getGraphBaseUrl(accessToken)}/${userId}?fields=is_user_follow_business&access_token=${accessToken}`);
      const data = await response.json();
      
      if (!response.ok) {
        console.error("Meta API - checkFollowStatus API Error:", data.error?.message);
        throw new Error(data.error?.message || "Failed to check follow status");
      }

      // Explicitly return success and the boolean value
      return { 
        success: true, 
        isFollowing: data.is_user_follow_business === true,
        exists: data.is_user_follow_business !== undefined
      };
    } catch (error) {
      console.error("Meta API - checkFollowStatus Throwable Error:", error.message);
      return { success: false, isFollowing: false, error: error.message };
    }
  },

  sendReaction: async (recipientId, messageId, emoji, accessToken) => {
    try {
      const response = await fetch(`${getGraphBaseUrl(accessToken)}/me/messages?access_token=${accessToken}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          recipient: { id: recipientId },
          sender_action: "react",
          payload: {
            mid: messageId,
            reaction: emoji
          }
        })
      });
      const data = await response.json();
      return { success: true, data };
    } catch (error) {
      console.error("Meta API - sendReaction Error:", error.message);
      return { success: false };
    }
  },

  getMediaContext: async (mediaId, accessToken) => {
    try {
      const response = await fetch(`${getGraphBaseUrl(accessToken)}/${mediaId}?fields=caption&access_token=${accessToken}`);
      const data = await response.json();
      if (!response.ok) throw new Error(data.error?.message || "Failed to fetch caption");
      return { success: true, caption: data.caption };
    } catch (error) {
      console.error("Meta API - getMediaContext Error:", error.message);
      return { success: false, caption: "" };
    }
  },

  sendFollowGateCard: async (recipientId, brandName, accessToken, profileIdentifier = null, customPayload = "VERIFY_FOLLOW_CLICKED", customTitle = null, customSubtitle = null) => {
    try {
      // Prefer handle links; fall back to the generic Instagram home if we only have a numeric id.
      let followLink = "https://www.instagram.com/";
      if (profileIdentifier) {
        const normalized = String(profileIdentifier).trim().replace(/^@/, "");
        const isNumericOnly = /^[0-9]+$/.test(normalized);
        const looksLikeHandle = /^[A-Za-z0-9._]+$/.test(normalized);
        if (!isNumericOnly && looksLikeHandle) {
          followLink = `https://www.instagram.com/${normalized}/`;
        }
      }
      const payload = {
        recipient: { id: recipientId },
        message: {
          attachment: {
            type: "template",
            payload: {
              template_type: "generic",
              elements: [{
                title: customTitle || "One final step to unlock!",
                subtitle: customSubtitle !== null && customSubtitle !== undefined ? customSubtitle : `Please follow @${brandName || 'us'} to get your link immediately.`,
                buttons: [
                  { type: "web_url", url: followLink, title: "Visit Profile" },
                  { type: "postback", title: "I am following", payload: customPayload }
                ]
              }]
            }
          }
        }
      };

      const response = await fetch(`${getGraphBaseUrl(accessToken)}/me/messages?access_token=${accessToken}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      const data = await response.json();
      if (!response.ok) {
        console.error(`Meta API FollowGate Error [${response.status}]:`, data.error?.message);
        throw new Error(data.error?.message || "Failed to send Follow-Gate card");
      }
      return { success: true };
    } catch {
      return { success: false };
    }
  },

  sendGenericCard: async (recipientId, title, subtitle, buttonTitle, url, accessToken, imageUrl = null) => {
    try {
      const payload = {
        recipient: { id: recipientId },
        message: {
          attachment: {
            type: "template",
            payload: {
              template_type: "generic",
              elements: [{
                title: title || "Exclusive Access!",
                subtitle: subtitle,
                image_url: imageUrl,
                buttons: [
                  {
                    type: "web_url",
                    url: url,
                    title: buttonTitle || "Open Link"
                  }
                ]
              }]
            }
          }
        }
      };

      const response = await fetch(`${getGraphBaseUrl(accessToken)}/me/messages?access_token=${accessToken}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      const data = await response.json();
      if (!response.ok) throw new Error(data.error?.message || "Failed to send generic card");
      return { success: true, data };
    } catch (error) {
      console.error("Meta API - sendGenericCard Error:", error.message);
      return { success: false, error: error.message };
    }
  },

  getMediaList: async (instagramId, accessToken, { limit } = {}) => {
    try {
      // Enhanced fields for Reels, Videos and Carousels
      const fields = "id,media_url,permalink,caption,timestamp,media_type,thumbnail_url,media_product_type,children{media_url,media_type}";
      const limitParam = Number.isFinite(limit) ? `&limit=${limit}` : "";
      let { response, data } = await fetchJson(
        `${INSTAGRAM_GRAPH_BASE_URL}/${instagramId}/media?fields=${fields}${limitParam}&access_token=${accessToken}`
      );

      if (!response.ok) {
        ({ response, data } = await fetchJson(
          `${BASE_URL}/${instagramId}/media?fields=${fields}${limitParam}&access_token=${accessToken}`
        ));
      }
      
      if (!response.ok) {
        console.error("Meta API getMediaList Error:", data.error?.message);
        throw new Error(data.error?.message || "Failed to fetch media list");
      }
      
      // Post-process to ensure even Carousels have a media_url for the UI
      const processedMedia = (data.data || []).map(item => ({
        ...item,
        media_url: item.media_url || (item.children?.data?.[0]?.media_url) || item.thumbnail_url
      }));

      return { success: true, data: processedMedia };
    } catch (error) {
      return { success: false, error: error.message };
    }
  },

  getStoriesList: async (instagramId, accessToken) => {
    try {
      const fields = "id,media_url,permalink,timestamp,media_type,thumbnail_url";
      let { response, data } = await fetchJson(
        `${INSTAGRAM_GRAPH_BASE_URL}/${instagramId}/stories?fields=${fields}&access_token=${accessToken}`
      );

      if (!response.ok) {
        ({ response, data } = await fetchJson(
          `${BASE_URL}/${instagramId}/stories?fields=${fields}&access_token=${accessToken}`
        ));
      }
      
      if (!response.ok) {
        console.error("Meta API getStoriesList Error:", data?.error?.message);
        throw new Error(data?.error?.message || "Failed to fetch stories list");
      }
      
      return { success: true, data: data.data || [] };
    } catch (error) {
      return { success: false, error: error.message };
    }
  },

  getCommentSenderUsername: async (commentId, accessToken) => {
    try {
      const response = await fetch(`${getGraphBaseUrl(accessToken)}/${commentId}?fields=from&access_token=${accessToken}`);
      const data = await response.json();
      if (!response.ok) throw new Error(data.error?.message || "Failed to fetch comment sender");
      return { success: true, username: data.from?.username };
    } catch (error) {
      console.error("Meta API - getCommentSenderUsername Error:", error.message);
      return { success: false, error: error.message };
    }
  },

  /**
   * Subscribe the Instagram account to the webhook app.
   */
  subscribeAccount: async (accessToken) => {
    try {
      const { response, data } = await fetchJson(
        `${INSTAGRAM_GRAPH_BASE_URL}/me/subscribed_apps`,
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            access_token: accessToken
          })
        }
      );

      if (!response.ok) {
        throw new Error(data?.error?.message || "Failed to subscribe account to webhooks");
      }

      return { success: true, data };
    } catch (error) {
      console.error("Meta API - subscribeAccount Error:", error.message);
      return { success: false, error: error.message };
    }
  }
};

// Legacy exports for compatibility
export const getUserProfile = MetaService.getUserProfile;
export const sendDM = MetaService.sendDM;
export const sendPrivateReply = MetaService.sendPrivateReply;
export const sendCommentReply = MetaService.sendCommentReply;
export const checkFollowStatus = MetaService.checkFollowStatus;
export const sendFollowGateCard = MetaService.sendFollowGateCard;
export const getMediaContext = MetaService.getMediaContext;
export const sendReaction = MetaService.sendReaction;
export const sendGenericCard = MetaService.sendGenericCard;
export const getMediaList = MetaService.getMediaList;
export const getStoriesList = MetaService.getStoriesList;
export const subscribeAccount = MetaService.subscribeAccount;
export const getCommentSenderUsername = MetaService.getCommentSenderUsername;


